130	export async function createContentGeneratorConfig(
131	  config: Config,
132	  authType: AuthType | undefined,
133	  apiKey?: string,
134	  baseUrl?: string,
135	  customHeaders?: Record<string, string>,
136	  vertexAiRouting?: VertexAiRoutingConfig,
137	): Promise<ContentGeneratorConfig> {
138	  const contentGeneratorConfig: ContentGeneratorConfig = {
139	    authType,
140	    proxy: config?.getProxy(),
141	    baseUrl,
142	    customHeaders,
143	    vertexAiRouting,
144	  };
145	
146	  // If we are using Google auth or we are in Cloud Shell, there is nothing else to validate for now.
147	  // Return before touching the API-key keychain: on Linux without a Secret Service
148	  // (WSL/SSH/Docker/CI) keytar can block indefinitely on its functional probe.
149	  if (
150	    authType === AuthType.LOGIN_WITH_GOOGLE ||
151	    authType === AuthType.COMPUTE_ADC
152	  ) {
153	    return contentGeneratorConfig;
154	  }
155	
156	  const geminiApiKey =
157	    apiKey ||
158	    process.env['GEMINI_API_KEY'] ||
159	    (await loadApiKey()) ||
160	    undefined;
161	  const googleApiKey = process.env['GOOGLE_API_KEY'] || undefined;
162	  const googleCloudProject =
163	    process.env['GOOGLE_CLOUD_PROJECT'] ||
164	    process.env['GOOGLE_CLOUD_PROJECT_ID'] ||
165	    undefined;
166	  const googleCloudLocation = process.env['GOOGLE_CLOUD_LOCATION'] || undefined;
167	
168	  if (authType === AuthType.USE_GEMINI && geminiApiKey) {
169	    contentGeneratorConfig.apiKey = geminiApiKey;
170	    contentGeneratorConfig.vertexai = false;
171	
172	    return contentGeneratorConfig;
173	  }
174	
175	  if (
176	    authType === AuthType.USE_VERTEX_AI &&
177	    (googleApiKey || (googleCloudProject && googleCloudLocation))
178	  ) {
179	    contentGeneratorConfig.apiKey = googleApiKey;
180	    contentGeneratorConfig.vertexai = true;
181	
182	    return contentGeneratorConfig;
183	  }
184	
185	  if (authType === AuthType.GATEWAY) {
186	    contentGeneratorConfig.apiKey =
187	      apiKey || process.env['GEMINI_API_KEY'] || '';
188	    contentGeneratorConfig.vertexai = false;
189	
190	    return contentGeneratorConfig;
191	  }
192	
193	  return contentGeneratorConfig;
194	}
